{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Glimepiride, the closest structural analogue sharing the phenethyl-sulfonylurea-cyclohexyl core, had 97% absolute oral bioavailability in healthy volunteers (90% CI 93-102%) versus IV, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Tolbutamide, another oral sulfonylurea, showed ~93% oral bioavailability in humans, reinforcing the class-level pattern of high sulfonylurea bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Sulpiride has low oral bioavailability (~27%) attributed to P-gp efflux and incomplete absorption, but it is a basic benzamide/sulfonamide rather than an acidic sulfonylurea and is much less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a glimepiride-like sulfonylurea; glimepiride and other sulfonylureas show near-complete oral bioavailability in humans, and the closest analogue evidence strongly supports F >= 20%. Low-F benzamide/sulfonamide analogues are less transferable due to different ionization and transporter liabilities.",
  "evidence_gaps": [
    "No direct human PK data for the exact query molecule.",
    "Metabolic stability and transporter interactions of the 2-methoxy-5-chlorobenzamide moiety are unmeasured.",
    "Formulation-dependent absorption was not assessed for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

